@layer components {
  .profile-card {
    border-width: var(--shelf-borderWidth-md);
    border-style: solid;
    border-color: var(--shelf-profileCard-borderColor-default);
    background-color: var(--shelf-profileCard-bgColor-surface);
    padding: var(--shelf-spacing-md);
  }

  .profile-card-title {
    color: var(--shelf-profileCard-fgColor-title);
    font-size: var(--shelf-fontSize-lg);
  }

  .profile-card-subtitle {
    color: var(--shelf-profileCard-fgColor-subtitle);
    font-size: var(--shelf-fontSize-sm);
  }

  .profile-card-skeleton-bar {
    background-color: var(--shelf-profileCard-bgColor-skeleton);
    height: var(--shelf-size-skeletonBar);
    border-radius: var(--shelf-borderRadius-sm);
    animation: shimmer var(--shelf-duration-slow) var(--shelf-easing-linear) infinite;
  }

  .profile-card-skeleton-bar--short {
    width: var(--shelf-size-skeletonBarShort);
  }

  @keyframes shimmer {
    0% {
      opacity: 1;
    }
    50% {
      opacity: var(--shelf-opacity-skeleton);
    }
    100% {
      opacity: 1;
    }
  }
}
